package com.eventmgr.web;
import com.eventmgr.util.*;import com.google.gson.JsonObject;import org.mindrot.jbcrypt.BCrypt;import javax.servlet.annotation.WebServlet;import javax.servlet.http.*;import java.io.*;import java.util.*;import java.util.regex.Pattern;
@WebServlet("/api/auth/*") public class AuthServlet extends ApiServlet {static final Pattern EMAIL=Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
 protected void doGet(HttpServletRequest q,HttpServletResponse r)throws IOException{String x=segs(q).length>0?segs(q)[0]:"";if(x.equals("me"))send(r,200,me(q));else if(x.equals("settings"))send(r,200,Map.of("siteName",Settings.get("site_name","EventX"),"allowRegistration",Settings.bool("allow_registration",true)));else throw new ApiError(404,"Not found");}
 protected void doPost(HttpServletRequest q,HttpServletResponse r)throws IOException{String x=segs(q).length>0?segs(q)[0]:"";if(x.equals("logout")){HttpSession s=q.getSession(false);if(s!=null)s.invalidate();message(r,200,"Signed out");return;}JsonObject b=body(q);if(x.equals("register")){if(!Settings.bool("allow_registration",true))throw new ApiError(403,"Registration is closed");String n=str(b,"name",true),e=str(b,"email",true).toLowerCase(),p=str(b,"password",true),role=str(b,"role",true);if(!EMAIL.matcher(e).matches())throw new ApiError(400,"Enter a valid email");if(!Set.of("ORGANIZER","ATTENDEE").contains(role))throw new ApiError(400,"Choose organizer or attendee");if(p.length()<6)throw new ApiError(400,"Password must be at least 6 characters");Db.insert("INSERT INTO users(name,email,password_hash,role) VALUES(?,?,?,?)",n,e,BCrypt.hashpw(p,BCrypt.gensalt()),role);Activity.log(null,"Account registered",n+" joined as "+role.toLowerCase());message(r,201,"Account created. You can sign in now.");return;}if(x.equals("login")){String e=str(b,"email",true).toLowerCase(),p=str(b,"password",true);Map<String,Object> u=Db.one("SELECT id,name,email,password_hash,role,status FROM users WHERE email=?",e);if(u==null)throw new ApiError(401,"Email or password is incorrect");String savedHash=(String)u.get("password_hash");boolean bootstrap="admin@eventmgr.local".equals(e)&&"ADMIN".equals(u.get("role"))&&"__BOOTSTRAP_ADMIN__".equals(savedHash);boolean valid=bootstrap?"Admin@123".equals(p):BCrypt.checkpw(p,savedHash);if(!valid)throw new ApiError(401,"Email or password is incorrect");if(!"ACTIVE".equals(u.get("status")))throw new ApiError(403,"Account suspended");if(bootstrap)Db.update("UPDATE users SET password_hash=? WHERE id=? AND password_hash=?",BCrypt.hashpw(p,BCrypt.gensalt()),u.get("id"),"__BOOTSTRAP_ADMIN__");HttpSession old=q.getSession(false);if(old!=null)old.invalidate();HttpSession s=q.getSession(true);User z=new User(((Number)u.get("id")).longValue(),(String)u.get("name"),(String)u.get("email"),(String)u.get("role"));s.setAttribute("user",z);s.setMaxInactiveInterval(28800);send(r,200,z);return;}throw new ApiError(404,"Not found");}}
